type ICounterField = IDisposable & { value: number }

function counterField(initial: number): IFieldBuilder<ICounterField> {
  return {
    [FIELD_BUILDER]: true,
    mode: 'sync',
    create({ createSource }: IFieldContext): ICounterField {
      const source = createSource('CounterField')
      let value = initial
      let disposed = false
      return {
        get value() {
          source.track()
          return value
        },
        set value(v) {
          source.commit(() => {
            value = v
          })
        },
        get disposed() {
          return disposed
        },
        dispose() {
          if (disposed) return
          disposed = true
          source.dispose()
        }
      }
    }
  }
}

