type IByCategory = IDiscriminatedByPath<IEvent, 'meta.category'>;
// { write: 'created' | 'deleted' 两个分支的联合; read: 'read' 分支 }

type IByTupleCategory = IDiscriminatedByPath<IEvent, readonly ['meta', 'category']>;
